    List<ItemCarrinho> itens = new ArrayList<>();
    itens.add(new ItemCarrinho("Produto", 10.0, 1, 0.5));

    ResumoRequest request = criarRequisicao(itens, "EXPRESSA", null, "INVALIDA", 1, "BRONZE", "NORTE");

